class GFG {

    // 8 directions of knight moves
    static int[] dx = { 2, 1, -1, -2, -2, -1, 1, 2 };
    static int[] dy = { 1, 2, 2, 1, -1, -2, -2, -1 };

    // Utility function to check if the
    // move is valid
    static boolean
    isSafe(int x, int y, int n,
           ArrayList<ArrayList<Integer> > board)
    {
        return (x >= 0 && y >= 0 && x < n && y < n
                && board.get(x).get(y) == -1);
    }

