    static boolean
    knightTourUtil(int x, int y, int step, int n,
                   ArrayList<ArrayList<Integer> > board)
    {
        // If all squares are visited
        if (step == n * n) {
            return true;
        }

        // Try all 8 possible knight moves
        for (int i = 0; i < 8; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (isSafe(nx, ny, n, board)) {
                board.get(nx).set(ny, step);

                if (knightTourUtil(nx, ny, step + 1, n,
                                   board)) {
                    return true;
                }

                // Backtrack
                board.get(nx).set(ny, -1);
            }
        }

        return false;
    }

    // Function to start Knight's Tour
    static ArrayList<ArrayList<Integer> > knightTour(int n)
    {
        ArrayList<ArrayList<Integer> > board
            = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            ArrayList<Integer> row = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                row.add(-1);
            }
            board.add(row);
        }

        // Start from top-left corner
        board.get(0).set(0, 0);

        if (knightTourUtil(0, 0, 1, n, board)) {
            return board;
        }

        return new ArrayList<>();
    }

    public static void main(String[] args)
    {
        int n = 5;
        ArrayList<ArrayList<Integer> > res = knightTour(n);

        for (ArrayList<Integer> row : res) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}


