    import java.util.*;

class GFG {

    // Count the number of onward moves from position (x, y)
    static int
    countOptions(ArrayList<ArrayList<Integer> > board,
                 int x, int y, int[][] dir)
    {
        int count = 0;
        int n = board.size();

        for (int i = 0; i < 8; i++) {
            int nx = x + dir[i][0];
            int ny = y + dir[i][1];

            if (nx >= 0 && ny >= 0 && nx < n && ny < n
                && board.get(nx).get(ny) == -1) {
                count++;
            }
        }
        return count;
    }

    // Generate valid knight moves from (x, y), sorted by
    // fewest onward moves
    static ArrayList<ArrayList<Integer> >
    getSortedMoves(ArrayList<ArrayList<Integer> > board,
                   int x, int y, int[][] dir)
    {
        ArrayList<ArrayList<Integer> > moveList
            = new ArrayList<>();
        int n = board.size();

        for (int i = 0; i < 8; i++) {
            int nx = x + dir[i][0];
            int ny = y + dir[i][1];

            if (nx >= 0 && ny >= 0 && nx < n && ny < n
                && board.get(nx).get(ny) == -1) {
                int options
                    = countOptions(board, nx, ny, dir);
                moveList.add(new ArrayList<>(
                    Arrays.asList(options, i)));
            }
        }

        // Sort using lexicographic comparison
        moveList.sort((a, b) -> {
            if (!a.get(0).equals(b.get(0))) {
                return Integer.compare(a.get(0), b.get(0));
            }
            return Integer.compare(a.get(1), b.get(1));
        });

        return moveList;
    }

    // Recursive function to solve the Knight's Tour
    static boolean knightTourUtil(int x, int y, int step, int n,
                   ArrayList<ArrayList<Integer> > board,
                   int[][] dir)
    {
        if (step == n * n)
            return true;

        ArrayList<ArrayList<Integer> > moves
            = getSortedMoves(board, x, y, dir);

        for (ArrayList<Integer> move : moves) {
            int dirIdx = move.get(1);
            int nx = x + dir[dirIdx][0];
            int ny = y + dir[dirIdx][1];

            board.get(nx).set(ny, step);

            if (knightTourUtil(nx, ny, step + 1, n, board,
                               dir))
                return true;

            // Backtrack
            board.get(nx).set(ny, -1);
        }
        return false;
    }

    // Function to start Knight's Tour
    static ArrayList<ArrayList<Integer> > knightTour(int n)
    {
        // Define 8 knight moves
        int[][] dir = { { 2, 1 },  { 1, 2 },   { -1, 2 },
                        { -2, 1 }, { -2, -1 }, { -1, -2 },
                        { 1, -2 }, { 2, -1 } };

        ArrayList<ArrayList<Integer> > board
            = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            ArrayList<Integer> row = new ArrayList<>();
            for (int j = 0; j < n; j++)
                row.add(-1);
            board.add(row);
        }

        // Start from top-left corner
        board.get(0).set(0, 0);

        if (knightTourUtil(0, 0, 1, n, board, dir)) {
            return board;
        }

        return new ArrayList<>();
    }

    public static void main(String[] args)
    {
        int n = 5;
        ArrayList<ArrayList<Integer> > result
            = knightTour(n);

        for (ArrayList<Integer> row : result) {
            for (int val : row)
                System.out.print(val + " ");
            System.out.println();
        }
